  var done=LV.repDone?'<p class="msub" role="status" style="margin:0 0 14px;font-size:16px"><b style="color:#1b1526">Thank you, we have it.</b> Your reference is <b style="color:#1b1526">'+esc(LV.repDone)+'</b>. You can follow it below.</p>':'';
