  var G=d.gifts||[],gifts='<div class="mcard"><span class="mtag">GIVING HISTORY</span>'+(G.length?'<table class="mtab"><thead><tr><th>Date</th><th>Amount</th><th>How</th></tr></thead><tbody>'+G.map(function(g){return '<tr><td>'+liveDate(g.gift_date,1)+'</td><td>'+money(+g.amount||0)+(g.is_recurring?' (monthly)':'')+'</td><td>'+esc(g.source||'')+'</td></tr>'}).join('')+'</tbody></table><p class="msub">'+G.length+' gift'+(G.length===1?'':'s')+', '+money(x.total)+' in all.</p>':'<p class="msub" style="margin:0">No gifts recorded for this member yet.</p>')+'</div>';
