  var as=(/^[ae]/.test(ro)?'an ':'a ')+liveRoleName(ro),fin=function(d){LV.roleBusy=false;if(!d||d.error){toast(d&&d.error==='not_allowed'?'That was not allowed.':'That did not go through. Please try again.');renderMember();return}
    var who=d.result==='granted'?em+' is now '+as+'.':em+' will become '+as+' the first time they log in.';toast(d.emailed?who+' We emailed them.':who+' The email could not be sent'+(d.reason==='not_set_up'?' (email sending is not set up yet)':'')+', so please tell them yourself.');LV.rows=null;renderMember()};
